mapper.select:
select v.id, v.tree_id, v.category_node_id, n.node_name as category_node_name, v.vin, v.plate_no, v.brand, v.create_time from biz_vehicle v left join biz_tree_node n on n.node_id = v.category_node_id and n.del_flag = '0'
v.del_flag = 0
and v.vin = #{bo.vin}
and v.plate_no = #{bo.plateNo}
and v.brand = #{bo.brand}
and v.tree_id = #{bo.treeId}
and v.category_node_id = #{bo.categoryNodeId}
order by v.id asc

select v.id, v.tree_id, v.category_node_id, n.node_name as category_node_name, v.vin, v.plate_no, v.brand, v.create_time from biz_vehicle v left join biz_tree_node n on n.node_id = v.category_node_id and n.del_flag = '0'
v.del_flag = 0
and v.vin = #{bo.vin}
and v.plate_no = #{bo.plateNo}
and v.brand = #{bo.brand}
and v.tree_id = #{bo.treeId}
and v.category_node_id = #{bo.categoryNodeId}
order by v.id asc
